            setattr(getattr(self.axes, lim_name), attr_name, (vmin, vmax))
        else:
            oldmin, oldmax = getter(self)
            # Check if the axis is inverted
            if self.axes.invert_xaxis() and method_name == 'view':
                setter(self, max(vmin, vmax), min(vmin, vmax), ignore=True)
            elif self.axes.invert_yaxis() and method_name == 'view':
                setter(self, max(vmin, vmax), min(vmin, vmax), ignore=True)
            else:
                setter(self, min(vmin, vmax, oldmin), max(vmin, vmax, oldmax), ignore=True)
        self.stale = True

    getter.__name__ = f"get_{method_name}_interval"
    setter.__name__ = f"set_{method_name}_interval"

    return getter, setter
